G=load()

def f(g):
    H,W=len(g),len(g[0])
    # block color = most common color that forms a rectangle? Use: the color forming largest solid rectangle != background
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # block color: second most common? demo bg=7 block=8; test bg=5 block=1
    colors=Counter(x for r in g for x in r)
    order=[c for c,_ in colors.most_common()]
    block=order[1] if len(order)>1 else None
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (bg,block)]
    out=[row[:] for row in g]
    for nr,nc,col in cells:
        best=None
        for r in range(H):
            for c in range(W):
                if g[r][c]==block:
                    key=abs(r-nr)+abs(c-nc)
                    if best is None or key<best[0]: best=(key,r,c)
        if best: out[best[1]][best[2]]=col
    return out

